import csv
from typing import Dict

def fx_rate(date: str) -> float:
    """Return the USD->EUR closing rate on the given date, read from data/ecb_rates_2019.csv."""
    with open('data/ecb_rates_2019.csv', 'r') as file:
        reader = csv.DictReader(file)
        for row in reader:
            if row['Date'] == date:
                return float(row['USD/EUR'])
    return 0.0

import pandas as pd

def fx_rate(date: str) -> float:
    df = pd.read_csv('data/ecb_rates_2019.csv', parse_dates=['Date'])
    df['Date'] = pd.to_datetime(df['Date']).dt.strftime('%Y-%m-%d')
    row = df[df['Date'] == date]
    return float(row['Rate'].values[0])

